{"path":"/root/solve.py","content":"import csv
import json
from pathlib import Path

ROOT = Path('/root')


def load_json(name):
    with (ROOT / name).open() as f:
        return json.load(f)


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def money(value):
    return round(float(value) + 0.0, 2)


def nonempty(value):
    return value is not None and str(value).strip() != ''


def main():
    manifest = load_json('panel_manifest.json')
    holdouts = load_json('holdouts.json')
    template = load_json('report_template.json')

    shipper_rows = load_csv('shipper_cost.csv')
    contract_rows = load_csv('contract_terms.csv')
    adjustment_rows = load_csv('network_adjustments.csv')
    override_rows = load_csv('lab_capacity_overrides.csv')

    excluded_codes = {
        row['panel_code']
        for row in holdouts.get('holdouts', [])
        if row.get('holdout_state') == 'exclude'
    }

    retained = []
    for cluster in manifest.get('service_clusters', []):
        for panel in cluster.get('panels', []):
            if panel.get('analysis_mode') == 'review' and panel.get('panel_code') not in excluded_codes:
                retained.append(panel)

    # Latest current contract row matched by panel_name or any alias label.
    contract_by_panel_code = {}
    for panel in retained:
        refs = {panel.get('panel_name', '')}
        refs.update(panel.get('alias_labels', []) or [])
        matches = [
            row for row in contract_rows
            if row.get('status_flag') == 'current' and row.get('panel_ref') in refs
        ]
        if not matches:
            raise ValueError(f"No current contract term found for {panel['panel_code']}")
        latest = max(matches, key=lambda row: row.get('effective_week', ''))
        contract_by_panel_code[panel['panel_code']] = latest

    adjustment_by_tier = {
        row['network_tier']: float(row['network_adjustment_per_run_per_lab_usd'])
        for row in adjustment_rows
    }

    shipper_cost_by_class = {
        row['shipper_class']: float(row['shipper_cost_usd'])
        for row in shipper_rows
    }

    # Highest numeric approved rev with non-empty active_labs per panel_code.
    override_by_panel_code = {}
    for row in override_rows:
        if row.get('approval') != 'approved':
            continue
        if not nonempty(row.get('rev')) or not nonempty(row.get('active_labs')):
            continue
        code = row['panel_code']
        rev = float(row['rev'])
        active_labs = float(row['active_labs'])
        current = override_by_panel_code.get(code)
        if current is None or rev > current['rev']:
            override_by_panel_code[code] = {'rev': rev, 'active_labs': active_labs}

    panel_outputs = []
    total_margin_14 = 0.0
    total_margin_28 = 0.0
    total_difference = 0.0

    for panel in sorted(retained, key=lambda p: p['panel_code']):
        code = panel['panel_code']
        contract = contract_by_panel_code[code]
        base_payment = float(contract['base_payment_per_run_per_lab_usd'])
        network_adjustment = adjustment_by_tier.get(panel.get('network_tier'), 0.0)
        total_payment = base_payment + network_adjustment

        if code in override_by_panel_code:
            active_labs = override_by_panel_code[code]['active_labs']
        else:
            active_labs = float(panel['default_active_labs'])

        shipper_class = panel['shipper_class']
        if shipper_class not in shipper_cost_by_class:
            raise ValueError(f"No shipper cost found for class {shipper_class}")
        shipper_cost = shipper_cost_by_class[shipper_class]
        reagent_cost_per_1000 = float(panel['reagent_cost_per_1000_tests_usd'])

        def model_financials(runs_per_year, tests_per_lab_per_run):
            annual_revenue = total_payment * active_labs * runs_per_year
            annual_reagent_cost = reagent_cost_per_1000 * active_labs * float(tests_per_lab_per_run) * runs_per_year / 1000.0
            # shipper_cost_usd column has no annual qualifier and magnitudes are per-shipment/per-run.
            annual_shipper_cost = shipper_cost * runs_per_year
            annual_margin = annual_revenue - annual_reagent_cost - annual_shipper_cost
            return annual_revenue, annual_reagent_cost, annual_shipper_cost, annual_margin

        rev14, reagent14, ship14, margin14 = model_financials(26, panel['tests_per_lab_per_run_14_day'])
        rev28, reagent28, ship28, margin28 = model_financials(13, panel['tests_per_lab_per_run_28_day'])
        diff = margin28 - margin14

        total_margin_14 += margin14
        total_margin_28 += margin28
        total_difference += diff

        # Keep panel objects flat: identifiers, resolved inputs, and computed financials.
        panel_outputs.append({
            'panel_code': code,
            'panel_name': panel['panel_name'],
            'network_tier': panel['network_tier'],
            'shipper_class': shipper_class,
            'active_labs': int(active_labs) if active_labs.is_integer() else active_labs,
            'base_payment_per_run_per_lab_usd': money(base_payment),
            'network_adjustment_per_run_per_lab_usd': money(network_adjustment),
            'total_payment_per_run_per_lab_usd': money(total_payment),
            'shipper_cost_usd': money(shipper_cost),
            'annual_revenue_14_day_usd': money(rev14),
            'annual_reagent_cost_14_day_usd': money(reagent14),
            'annual_shipper_cost_14_day_usd': money(ship14),
            'annual_margin_14_day_usd': money(margin14),
            'annual_revenue_28_day_usd': money(rev28),
            'annual_reagent_cost_28_day_usd': money(reagent28),
            'annual_shipper_cost_28_day_usd': money(ship28),
            'annual_margin_28_day_usd': money(margin28),
            'annual_margin_difference_28_minus_14_usd': money(diff),
        })

    totals = {
        'total_annual_margin_14_day_usd': money(total_margin_14),
        'total_annual_margin_28_day_usd': money(total_margin_28),
        'total_annual_margin_difference_28_minus_14_usd': money(total_difference),
        'absolute_total_margin_difference_usd': money(abs(total_difference)),
    }

    decision = 'adopt_28_day' if totals['absolute_total_margin_difference_usd'] < 6000 else 'keep_14_day'
    justification = (
        f"Absolute total margin difference is ${totals['absolute_total_margin_difference_usd']:,.2f}, "
        f"compared with the $6,000.00 switch threshold; decision is {decision}."
    )

    report = {
        'metadata': template['metadata'],
        'audit_notes': template['audit_notes'],
        'analysis': {
            'assumptions': {
                'runs_per_year_14_day': 26,
                'runs_per_year_28_day': 13,
                'switch_threshold_usd': 6000,
                'override_rule': 'highest numeric approved rev with non-empty active_labs, else default_active_labs',
                'holdout_rule': 'exclude holdout_state=exclude',
                'adjustment_rule': 'missing network_tier adjustment defaults to 0.0',
            },
            'panels': panel_outputs,
            'totals': totals,
            'recommendation': {
                'decision': decision,
                'justification': justification,
            },
        },
    }

    with (ROOT / 'diagpanel_policy_report.json').open('w') as f:
        json.dump(report, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# Diagpanel Policy Summary',
        '',
        f"Total 14-day annual margin: ${totals['total_annual_margin_14_day_usd']:,.2f}",
        f"Total 28-day annual margin: ${totals['total_annual_margin_28_day_usd']:,.2f}",
        f"Absolute margin difference: ${totals['absolute_total_margin_difference_usd']:,.2f}",
        f"Final decision: {decision}",
    ]
    (ROOT / 'diagpanel_policy_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
